from pathlib import Path

path = Path('/home/ubuntu/marketing-agent-dashboard/frontend/index.html')
h = path.read_text()
start = h.find('function renderPostResult')
end = h.find('async function generatePost', start)
if start < 0 or end < 0:
    raise SystemExit('renderer boundaries not found')
new_fn = r'''function renderPostResult(raw,format){const source=String(raw||'').trim();const labels=[['Contexto estratégico',['Contexto estratégico','Introdução estratégica','Contexto']],['Post',['Post','Título','Título do post']],['Objetivo',['Objetivo']],['Melhor dia e horário',['Melhor dia e horário','Melhor horário','Horário']],['Tipo de conteúdo',['Tipo de conteúdo','Formato']],['Legenda completa',['Legenda completa','Legenda']],['Hashtags principais',['Hashtags principais','Hashtags sugeridas','Hashtags']],['Hashtags ampliadas',['Hashtags ampliadas','Lista ampliada']],['Sugestão visual',['Sugestão visual','Direção visual']],['Música',['Música','Trilha']],['Dica de engajamento',['Dica de engajamento','Dicas de engajamento','Engajamento']],['Conclusão estratégica',['Conclusão estratégica','Conclusão','Posicionamento esperado']],['Roteiro / estrutura',['Roteiro / estrutura','Roteiro']]];const escapeRegExp=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const headingPatterns=labels.flatMap(([,keys])=>keys.map(escapeRegExp));const headingRe=new RegExp('^\\s*(?:'+headingPatterns.join('|')+')\\s*[:\\-]?(?:\\s|$)','i');const sections=labels.map(([title,keys])=>{const keyRe=keys.map(escapeRegExp).join('|');const inlineRe=new RegExp('^\\s*(?:'+keyRe+')\\s*[:\\-]\\s*(.*)$','i');const lines=source.split(/\\r?\\n/);let begin=-1;let body=[];for(let i=0;i<lines.length;i++){const inline=lines[i].match(inlineRe);if(inline){begin=i;body=inline[1]?[inline[1]]:[];break}}if(begin<0){const plainRe=new RegExp('^\\s*(?:'+keyRe+')\\s*$','i');const index=lines.findIndex(line=>plainRe.test(line));if(index<0)return {title,body:''};begin=index}for(let i=begin+1;i<lines.length;i++){if(headingRe.test(lines[i]))break;body.push(lines[i])}return {title,body:body.join('\\n').trim()}});const finalSections=sections.map(s=>({title:s.title,body:s.body||'Será preenchido pelo Agente de Marketing Digital conforme o briefing.'}));return '<div class="post-result-intro"><b>Leitura editorial:</b> a sugestão foi organizada para conectar contexto, tensão humana, ideia central e próxima ação, mantendo a profundidade sem perder concisão.</div><div class="result-grid detailed-result">'+finalSections.map(s=>'<div class="result-card"><strong>'+s.title+'</strong><p>'+escapePostHtml(s.body)+'</p></div>').join('')+'</div><div class="result-raw"><strong>Material completo para revisão</strong><p>'+escapePostHtml(source)+'</p></div>'}'''
h = h[:start] + new_fn + h[end:]
path.write_text(h)
print('post-renderer-rewritten')
